import strawberry
from datetime import datetime
from typing import Optional

from graphql import GraphQLError
from sqlalchemy import func, select
from sqlalchemy.exc import DataError, IntegrityError

from app import models
from app.db import SessionLocal


def _not_found(entity: str, key) -> GraphQLError:
    return GraphQLError(f"{entity} {key} not found", extensions={"code": "NOT_FOUND"})


def _require(data: dict, fields: tuple[str, ...]) -> None:
    # Same rule as the REST validators: required strings must not be empty.
    for name in fields:
        if data.get(name) == "":
            raise GraphQLError(f"{name} must not be empty", extensions={"code": "BAD_USER_INPUT"})


def _lookup(db, model, key):
    try:
        return db.get(model, key)
    except DataError:  # e.g. a malformed UUID on Postgres
        db.rollback()
        return None


def _commit(db) -> None:
    try:
        db.commit()
    except (IntegrityError, DataError) as exc:
        db.rollback()
        raise GraphQLError(f"Invalid input: {exc.orig}", extensions={"code": "BAD_USER_INPUT"}) from exc


@strawberry.type
class User:
    id: strawberry.ID
    name: str
    email: str
    active: bool
    createdAt: datetime


@strawberry.type
class Post:
    id: strawberry.ID
    title: str
    body: str
    published: bool


@strawberry.input
class CreateUserInput:
    name: str
    email: str
    active: bool
    createdAt: datetime


@strawberry.input
class UpdateUserInput:
    id: strawberry.ID
    name: str
    email: str
    active: bool
    createdAt: datetime


@strawberry.input
class CreatePostInput:
    title: str
    body: str
    published: bool


@strawberry.input
class UpdatePostInput:
    id: strawberry.ID
    title: str
    body: str
    published: bool


@strawberry.type
class UsersPage:
    items: list[User]
    total: int
    page: int
    page_size: int


@strawberry.type
class PostsPage:
    items: list[Post]
    total: int
    page: int
    page_size: int


def _user_out(row: models.User) -> User:
    return User(
        id=str(row.id) if row.id is not None else None,
        name=row.name,
        email=row.email,
        active=row.active,
        createdAt=row.createdAt,
    )


def _post_out(row: models.Post) -> Post:
    return Post(
        id=str(row.id) if row.id is not None else None,
        title=row.title,
        body=row.body,
        published=row.published,
    )


@strawberry.type
class Query:
    @strawberry.field
    def health(self) -> str:
        return "ok"

    @strawberry.field
    def list_users(self, page: int = 1, page_size: int = 20) -> UsersPage:
        page = max(1, page)
        page_size = max(1, min(100, page_size))
        with SessionLocal() as db:
            total = db.scalar(select(func.count()).select_from(models.User))
            rows = db.scalars(
                select(models.User)
                .order_by(models.User.id)
                .offset((page - 1) * page_size)
                .limit(page_size)
            ).all()
            return UsersPage(items=[_user_out(r) for r in rows], total=total, page=page, page_size=page_size)

    @strawberry.field
    def get_user(self, id: strawberry.ID) -> Optional[User]:
        with SessionLocal() as db:
            row = _lookup(db, models.User, id)
            return _user_out(row) if row is not None else None

    @strawberry.field
    def list_posts(self, page: int = 1, page_size: int = 20) -> PostsPage:
        page = max(1, page)
        page_size = max(1, min(100, page_size))
        with SessionLocal() as db:
            total = db.scalar(select(func.count()).select_from(models.Post))
            rows = db.scalars(
                select(models.Post)
                .order_by(models.Post.id)
                .offset((page - 1) * page_size)
                .limit(page_size)
            ).all()
            return PostsPage(items=[_post_out(r) for r in rows], total=total, page=page, page_size=page_size)

    @strawberry.field
    def get_post(self, id: strawberry.ID) -> Optional[Post]:
        with SessionLocal() as db:
            row = _lookup(db, models.Post, id)
            return _post_out(row) if row is not None else None


@strawberry.type
class Mutation:
    @strawberry.mutation
    def create_user(self, input: CreateUserInput) -> User:
        data = strawberry.asdict(input)
        _require(data, ("name", "email"))
        with SessionLocal() as db:
            row = models.User(**data)
            db.add(row)
            _commit(db)
            db.refresh(row)
            return _user_out(row)

    @strawberry.mutation
    def update_user(self, input: UpdateUserInput) -> User:
        data = strawberry.asdict(input)
        key = data.pop("id")
        _require(data, ("name", "email"))
        with SessionLocal() as db:
            row = _lookup(db, models.User, key)
            if row is None:
                raise _not_found("User", key)
            for name, value in data.items():  # full replace, as declared by UpdateUserInput
                setattr(row, name, value)
            _commit(db)
            db.refresh(row)
            return _user_out(row)

    @strawberry.mutation
    def delete_user(self, id: strawberry.ID) -> bool:
        with SessionLocal() as db:
            row = _lookup(db, models.User, id)
            if row is None:
                raise _not_found("User", id)
            db.delete(row)
            _commit(db)
            return True

    @strawberry.mutation
    def create_post(self, input: CreatePostInput) -> Post:
        data = strawberry.asdict(input)
        _require(data, ("title",))
        with SessionLocal() as db:
            row = models.Post(**data)
            db.add(row)
            _commit(db)
            db.refresh(row)
            return _post_out(row)

    @strawberry.mutation
    def update_post(self, input: UpdatePostInput) -> Post:
        data = strawberry.asdict(input)
        key = data.pop("id")
        _require(data, ("title",))
        with SessionLocal() as db:
            row = _lookup(db, models.Post, key)
            if row is None:
                raise _not_found("Post", key)
            for name, value in data.items():  # full replace, as declared by UpdatePostInput
                setattr(row, name, value)
            _commit(db)
            db.refresh(row)
            return _post_out(row)

    @strawberry.mutation
    def delete_post(self, id: strawberry.ID) -> bool:
        with SessionLocal() as db:
            row = _lookup(db, models.Post, id)
            if row is None:
                raise _not_found("Post", id)
            db.delete(row)
            _commit(db)
            return True


schema = strawberry.Schema(query=Query, mutation=Mutation)

